import{_ as t,a as n}from"./chunks/run-lifecycle-dark.DwoIKWq9.js";import{_ as a,o as s,c as o,a2 as d}from"./chunks/framework.Di-jvWLj.js";const f=JSON.parse('{"title":"Run Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"guide/run-lifecycle.md","filePath":"guide/run-lifecycle.md","lastUpdated":1793092669000}'),c={name:"guide/run-lifecycle.md"};function r(l,e,i,p,u,h){return s(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="run-lifecycle" tabindex="-1">Run Lifecycle <a class="header-anchor" href="#run-lifecycle" aria-label="Permalink to &quot;Run Lifecycle&quot;">​</a></h1><p>A run has exactly one of seven statuses. <code>RunStatus</code> is an enum of them, and <code>RunStatusLiteral</code> is the union of its string values, which is the type of <code>run.status</code>: compare against the enum, or against the plain string when that reads better.</p><table tabindex="0"><thead><tr><th>Status</th><th><code>RunStatus</code></th><th>Meaning</th><th>Final</th></tr></thead><tbody><tr><td><code>queued</code></td><td><code>QUEUED</code></td><td>Stored, waiting for a free slot, a free concurrency key and a claim</td><td>no</td></tr><tr><td><code>running</code></td><td><code>RUNNING</code></td><td>Claimed by one engine, which drives the model and writes steps and checkpoints</td><td>no</td></tr><tr><td><code>waiting</code></td><td><code>WAITING</code></td><td>Paused on a tool call that needs approval; holds no claim and no slot</td><td>no</td></tr><tr><td><code>interrupted</code></td><td><code>INTERRUPTED</code></td><td>Aborted by <code>drain()</code>; claim released, waits for <code>recover()</code></td><td>no</td></tr><tr><td><code>completed</code></td><td><code>COMPLETED</code></td><td>The model finished; <code>output</code> holds the text of its last answer, or the parsed value when the agent defines <a href="/guide/agents#structured-output">structured <code>output</code></a></td><td>yes</td></tr><tr><td><code>failed</code></td><td><code>FAILED</code></td><td>A budget, a timeout, a <code>FatalToolError</code>, a failed or incomplete model call, an output that does not parse, or an infrastructure error ended it; <code>error</code> holds <code>{ code, message }</code></td><td>yes</td></tr><tr><td><code>cancelled</code></td><td><code>CANCELLED</code></td><td><code>cancel()</code> ended it</td><td>yes</td></tr></tbody></table><div class="figure"><img class="only-light" src="'+t+'" alt="dispatch() stores a queued run, deduplicated by idempotency key. The engine claims it and runs it: every LLM or tool step is followed by a checkpoint in the store. A run ends completed, failed or cancelled. A tool call that needs approval pauses the run in waiting until it is answered; approving or denying it requeues the run. drain() or a crashed process leaves a run interrupted or with an expired claim; recover() requeues it, and the next execution continues from the latest checkpoint."><img class="only-dark" src="'+n+`" alt="" aria-hidden="true"></div><h2 id="transitions" tabindex="-1">Transitions <a class="header-anchor" href="#transitions" aria-label="Permalink to &quot;Transitions&quot;">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span>dispatch ----------------------------&gt; queued</span></span>
<span class="line"><span>queued   -- slot, key and claim -----&gt; running</span></span>
<span class="line"><span>running  -- model finished ----------&gt; completed</span></span>
<span class="line"><span>running  -- budget, timeout, fatal --&gt; failed</span></span>
<span class="line"><span>running  -- cancel() ----------------&gt; cancelled</span></span>
<span class="line"><span>running  -- a tool awaits approve() --&gt; waiting</span></span>
<span class="line"><span>waiting  -- answered or timed out ---&gt; queued     (then running again)</span></span>
<span class="line"><span>waiting  -- cancel() ----------------&gt; cancelled</span></span>
<span class="line"><span>running  -- drain() -----------------&gt; interrupted</span></span>
<span class="line"><span>interrupted -- recover() ------------&gt; queued     (then running again)</span></span>
<span class="line"><span>running, claim expired (crash) -- recover() --&gt; queued</span></span>
<span class="line"><span>queued   -- cancel() ----------------&gt; cancelled</span></span></code></pre></div><p>Every non-final status can come back to <code>queued</code>. The next execution always starts from the latest <a href="/guide/execution">checkpoint</a>, so work that completed before the pause, the drain or the crash is not repeated.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><p>While a run executes, the engine appends <code>Step</code> records to the store:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Written when</th><th><code>name</code></th><th><code>input</code> / <code>output</code></th></tr></thead><tbody><tr><td><code>llm</code></td><td>after every model call, a failed one included (finish reason <code>error</code>)</td><td>the model id</td><td>output: text, tool calls, finish reason, token usage</td></tr><tr><td><code>tool</code></td><td>for every tool result or tool error of that step</td><td>the tool name</td><td>the tool input and its output, or <code>error: { code, message }</code> (<code>tool_not_allowed</code> for a call to a tool the <a href="/guide/tools#restricting-tools-per-invoker"><code>toolPolicy</code></a> refuses)</td></tr><tr><td><code>wait</code></td><td>when an approval is answered</td><td>the tool name</td><td>input <code>{ toolCallId, title, body? }</code>; output <code>{ approvalId, approved, reason, approver? }</code></td></tr></tbody></table><p>Steps are append-only and numbered per run (<code>index</code>). They are the run&#39;s audit log; the checkpoint, not the steps, is what a resumed run continues from.</p><h2 id="watching-runs" tabindex="-1">Watching runs <a class="header-anchor" href="#watching-runs" aria-label="Permalink to &quot;Watching runs&quot;">​</a></h2><p><code>engine.on()</code> subscribes to <code>run.updated</code> (any status, usage or wait point change), <code>step.appended</code> and <code>run.delta</code> (model output while it streams, see <a href="/guide/execution#streaming">Streaming</a>). It returns an unsubscribe function. A listener that throws is reported to <code>onError</code> and does not affect the run.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> offRun = engine.on(</span><span style="color:#E7C58C;">&#39;run.updated&#39;</span><span style="color:#E6DFDE;">, (event) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">    if</span><span style="color:#E6DFDE;"> (event.type === </span><span style="color:#E7C58C;">&#39;run.updated&#39;</span><span style="color:#E6DFDE;">) {</span></span>
<span class="line"><span style="color:#E6DFDE;">        console.log(event.run.id, event.run.status);</span></span>
<span class="line"><span style="color:#E6DFDE;">    }</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> offStep = engine.on(</span><span style="color:#E7C58C;">&#39;step.appended&#39;</span><span style="color:#E6DFDE;">, (event) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">    if</span><span style="color:#E6DFDE;"> (event.type === </span><span style="color:#E7C58C;">&#39;step.appended&#39;</span><span style="color:#E6DFDE;">) {</span></span>
<span class="line"><span style="color:#E6DFDE;">        console.log(event.step.runId, event.step.index, event.step.kind);</span></span>
<span class="line"><span style="color:#E6DFDE;">    }</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>engine.getRun(id)</code> reads the current state from the store. <code>engine.idle()</code> resolves once nothing is running in this process and nothing more can be started, which is useful in tests and scripts.</p>`,15)])])}const m=a(c,[["render",r]]);export{f as __pageData,m as default};
